files.manifest.json:
{
  "name": "customer_late_payment_reminders",
  "kind": "workflow",
  "description": "Finds customer invoices unpaid past due date, computes days late and amounts, and drafts a short polite reminder for each customer.",
  "signature": {
    "in": "{\"type\":\"object\",\"properties\":{\"folder\":{\"type\":\"string\"},\"as_of_date\":{\"type\":\"string\"},\"customer_filter\":{\"type\":\"string\"},\"min_days_late\":{\"type\":\"integer\"},\"tone\":{\"type\":\"string\"}},\"required\":[\"folder\"]}",
    "out": "output of s3"
  },
  "steps": [
    {
      "id": "s1",
      "uses": "parse_bank_and_customer_ledgers",
      "foreach": null,
      "inputs": [
        {
          "param": "folder",
          "source": "$input.folder"
        }
      ]
    },
    {
      "id": "s2",
      "uses": "find_overdue_customer_invoices",
      "foreach": null,
      "inputs": [
        {
          "param": "customer_invoices",
          "source": "$steps.s1.customer_invoices"
        },
        {
          "param": "bank_transactions",
          "source": "$steps.s1.bank_transactions"
        },
        {
          "param": "as_of_date",
          "source": "$input.as_of_date"
        },
        {
          "param": "customer_filter",
          "source": "$input.customer_filter"
        },
        {
          "param": "min_days_late",
          "source": "$input.min_days_late"
        }
      ]
    },
    {
      "id": "s3",
      "uses": "write_payment_reminder",
      "foreach": "$steps.s2.overdue",
      "inputs": [
        {
          "param": "customer",
          "source": "$item.customer"
        },
        {
          "param": "invoice_number",
          "source": "$item.invoice_number"
        },
        {
          "param": "amount_czk",
          "source": "$item.outstanding_czk"
        },
        {
          "param": "due_date",
          "source": "$item.due_date"
        },
        {
          "param": "days_late",
          "source": "$item.days_late"
        },
        {
          "param": "tone",
          "source": "$input.tone"
        }
      ]
    }
  ],
  "output_step": "s3",
  "permissions": {
    "net": [],
    "llm": true
  },
  "budget": {
    "max_tokens_per_run": 6000
  },
  "lineage": {
    "created_by": "factory",
    "uses": [
      "parse_bank_and_customer_ledgers@v1",
      "find_overdue_customer_invoices@v1",
      "write_payment_reminder@v1"
    ]
  },
  "example_input": "{\"folder\":\"novak_trading\",\"as_of_date\":\"2026-10-09\",\"min_days_late\":1,\"tone\":\"polite\"}",
  "purpose": "a bot that lists which customers are late paying us, how many days late and how much, with a short polite reminder for each\n\nFiles: folder novak_trading",
  "version": 1,
  "build_usd": 0.0936,
  "build_seconds": 75,
  "headline": "{items.length} overdue invoices totaling {total_amount} CZK across {unique_customers} customers",
  "examples": [
    "Show me all customers who are late paying",
    "Which invoices are more than 5 days overdue?",
    "Generate payment reminders for Moravia Consult"
  ],
  "voice": "ghoul",
  "manual_minutes": 45.0,
  "manual_basis": "Extracting overdue invoices from accounting records, calculating days late, summing amounts, and composing personalized reminder letters."
}

